import{mean,pct,pearson}from'./stats.js';import{RULES,confidence}from'./config.js';import{compareCategories,compareRecent}from'./attendance.js';
export function socialReach(rows){const pairs=rows.filter(r=>r.reach!=null),positive=pairs.filter(r=>r.reach>0),c=compareRecent(rows),recent=pairs.filter(r=>c.recentIds.includes(r.id)),previous=pairs.filter(r=>c.previousIds.includes(r.id));const correlation=pairs.length>=RULES.correlation?pearson(pairs.map(r=>[r.reach,r.attendance])):null;return{available:pairs.length>0,sampleSize:pairs.length,averageReach:mean(pairs.map(r=>r.reach)),correlation,correlationEligible:pairs.length>=RULES.correlation,trend:c.available&&recent.length===c.recentCount&&previous.length===c.previousCount?{recent:mean(recent.map(r=>r.reach)),previous:mean(previous.map(r=>r.reach)),percentChange:pct(mean(recent.map(r=>r.reach)),mean(previous.map(r=>r.reach)))}:null,points:pairs.map(r=>({reach:r.reach,attendance:r.attendance,id:r.id,name:r.name})),excludedRows:rows.filter(r=>r.reach==null).map(r=>({id:r.id,reason:'Social reach missing or invalid.'})),warnings:[...(pairs.length<RULES.correlation?[`At least ${RULES.correlation} complete reach/attendance pairs are needed for a correlation.`]:correlation==null?['Correlation is unavailable when reach or attendance has no variation.']:[]),'Social reach and attendance are observational. Zero means no reach; missing values are excluded.'],confidence:confidence(pairs.length,rows.length?1-pairs.length/rows.length:1)}}
export function conversionRates(rows){const usable=rows.filter(r=>r.reach>0),signupRows=usable.filter(r=>r.signups!=null);const totals=a=>a.reduce((s,r)=>s+r.reach,0);return{available:usable.length>0,sampleSize:usable.length,attendancePerReach:usable.length?usable.reduce((s,r)=>s+r.attendance,0)/totals(usable):null,signupsPerReach:signupRows.length?signupRows.reduce((s,r)=>s+r.signups,0)/totals(signupRows):null,signupSampleSize:signupRows.length,excludedRows:rows.filter(r=>r.reach==null||r.reach===0).map(r=>({id:r.id,reason:r.reach==null?'Missing reach.':'Zero reach: division is undefined.'})),warnings:['These are aggregate attendance/reach and signup/reach ratios, not attributed conversion rates. Visitors may arrive through other channels; ratios can exceed 100%.'],confidence:confidence(usable.length)}}
export function promotionAnalysis(rows,retention){const comparison=compareCategories(rows,'promotion',retention);return{...comparison,groups:comparison.groups.map(g=>{const subset=rows.filter(r=>r.promotion===g.name);return{...g,averageSignups:mean(subset.filter(r=>r.signups!=null).map(r=>r.signups)),signupMeetings:subset.filter(r=>r.signups!=null).length,ratios:conversionRates(subset)}})}}
